def build_turn_user_content(goal: str, state: Dict[str, Any], history: List[Dict[str, str]], current_text: str, running_tasks: Optional[List[str]] = None, seconds_since_ai_spoke: Optional[float] = None) -> str:
    """Build one-turn model input."""
    payload: Dict[str, Any] = {
        "goal": goal, "state": state, "history": history[-12:], "current_user_text": current_text,
        "running_task_instructions": running_tasks or [],
        "seconds_since_ai_last_spoke": seconds_since_ai_spoke,
    }
    return json.dumps(payload, ensure_ascii=False)


def build_summary_user_content(state: Dict[str, Any]) -> str:
    """Build summary input; accepts a state or a record."""
    actual: Any = state.get("state", state) if isinstance(state, dict) else state
    return json.dumps({"state": actual}, ensure_ascii=False)


def build_search_user_content(instruction: str, goal: str = "", state: Optional[Dict[str, Any]] = None) -> str:
    """Build search input."""
    return json.dumps({"instruction": instruction, "goal": goal, "state": state or {}}, ensure_ascii=False)


def build_draft_user_content(instruction: str, goal: str, state: Dict[str, Any]) -> str:
    """Build draft input."""
    return json.dumps({"instruction": instruction, "goal": goal, "state": state}, ensure_ascii=False)


def build_sketch_user_content(goal: str, state: Dict[str, Any]) -> str:
    """Text accompanying a sketch image."""
    return json.dumps({"goal": goal, "state": state, "instruction": "描述这张纸上草稿并提取可见要点"}, ensure_ascii=False)
", "path": "app/prompts.py"}, {"content": """"Background search and drafting tasks."""
import json
import logging
import threading
import uuid
from concurrent.futures import ThreadPoolExecutor
from typing import Any, Dict, List, Optional, Tuple
from urllib.parse import urlparse

from muse_client import DEFAULT_MODEL, create_client
from app import store
from app.prompts import DRAFT_SYSTEM_PROMPT, SEARCH_SYSTEM_PROMPT, build_draft_user_content, build_search_user_content

logger: logging.Logger = logging.getLogger(__name__)
_executor: ThreadPoolExecutor = ThreadPoolExecutor(max_workers=4)
BUDGET_MESSAGE: str = "预算已耗尽，本次无法继续，请稍后再试。"


def is_budget_error(exc: Exception) -> bool:
    """Detect HTTP 402."""
    if getattr(exc, "status_code", None) == 402:
        return True
    return getattr(getattr(exc, "response", None), "status_code", None) == 402


def _attr(value: Any, name: str) -> Any:
    if isinstance(value, dict):
        return value.get(name)
    return getattr(value, name, None)


def _text_blocks(message: Any) -> Tuple[str, List[str]]:
    texts: List[str] = []
    urls: List[str] = []
    content: Any = _attr(message, "content")
    if isinstance(content, str):
        return content, urls
    if isinstance(content, list):
        for block in content:
            text: Any = _attr(block, "output_text")
            if not isinstance(text, str):
                text = _attr(block, "text")
            if isinstance(text, str):
                texts.append(text)
            annotations: Any = _attr(block, "annotations") or []
            if isinstance(annotations, list):
                for ann in annotations:
                    url: Any = _attr(ann, "url")
                    if isinstance(url, str):
                        urls.append(url)
    return "".join(texts), urls


def _message_text_and_sources(resp: Any) -> Tuple[str, List[Dict[str, str]]]:
    output: Any = _attr(resp, "output")
    if not isinstance(output, list):
        text: Any = _attr(resp, "output_text")
        return (text if isinstance(text, str) else ""), []
    messages: List[Any] = [item for item in output if _attr(item, "type") == "message"]
    text: str = ""
    sources: List[Dict[str, str]] = []
    seen: set = set()
    def add_source(title: str, url: str) -> None:
        parsed: Any = urlparse(url)
        if parsed.scheme not in ("http", "https") or url in seen or len(sources) >= 8:
            return
        seen.add(url)
        sources.append({"title": title or url, "url": url})
    if messages:
        text, urls = _text_blocks(messages[-1])
        for url in urls:
            add_source(url, url)
    for item in output:
        if _attr(item, "type") != "web_search_call":
            continue
        results: Any = _attr(item, "results") or []
        if isinstance(results, list):
            for result in results:
                url: Any = _attr(result, "url")
                title: Any = _attr(result, "title")
                if isinstance(url, str):
                    add_source(title if isinstance(title, str) else url, url)
    if not text:
        fallback: Any = _attr(resp, "output_text")
        text = fallback if isinstance(fallback, str) else ""
    return text, sources


def _split_conclusion(text: str) -> Tuple[str, str]:
    clean: str = text.strip()
    for index, char in enumerate(clean):
        if char in "。！？\n" or (char == "." and index + 1 < len(clean) and clean[index + 1] in " \n"):
            return clean[: index + 1].strip(), clean[index + 1 :].strip()
    return clean, ""


def _finish_task(session_id: str, task_id: str, status: str, conclusion: str, detail: str, sources: List[Dict[str, str]], announcement: str) -> None:
    with store.get_lock(session_id):
        record: Optional[Dict[str, Any]] = store.get_session(session_id)
        if record is None:
            return
        for task in record.get("tasks", []):
            if isinstance(task, dict) and task.get("id") == task_id:
                task.update({"status": status, "conclusion": conclusion, "detail": detail, "sources": sources})
        store.save_session(record)
    store.add_announcement(session_id, announcement)


def _run_search(record_goal: str, state: Dict[str, Any], instruction: str) -> Tuple[str, str, List[Dict[str, str]]]:
    client: Any = create_client()
    resp: Any = client.responses.create(
        model=DEFAULT_MODEL,
        input=[{"role": "system", "content": SEARCH_SYSTEM_PROMPT}, {"role": "user", "content": build_search_user_content(instruction, record_goal, state)}],
        max_output_tokens=4000, reasoning={"effort": "low"},
        tools=[{"type": "web_search", "search_context_size": "medium"}], include=["web_search_call.results"],
    )
    status: Any = _attr(resp, "status")
    if isinstance(status, str) and status != "completed":
        raise RuntimeError("search incomplete")
    text, sources = _message_text_and_sources(resp)
    if not text.strip():
        raise RuntimeError("empty search result")
    conclusion, detail = _split_conclusion(text)
    return conclusion, detail, sources


def _run_draft(goal: str, state: Dict[str, Any], instruction: str) -> str:
    client: Any = create_client()
    resp: Any = client.responses.create(
        model=DEFAULT_MODEL,
        input=[{"role": "system", "content": DRAFT_SYSTEM_PROMPT}, {"role": "user", "content": build_draft_user_content(instruction, goal, state)}],
        max_output_tokens=6000, reasoning={"effort": "medium"},
    )
    status: Any = _attr(resp, "status")
    if isinstance(status, str) and status != "completed":
        raise RuntimeError("draft incomplete")
    text, _ = _message_text_and_sources(resp)
    if not text.strip():
        raise RuntimeError("empty draft")
    return text.strip()


def run_task(session_id: str, task_id: str) -> None:
    """Run one task synchronously; used by the executor and tests."""
    with store.get_lock(session_id):
        record: Optional[Dict[str, Any]] = store.get_session(session_id)
        if record is None:
            return
        task: Optional[Dict[str, Any]] = next((t for t in record.get("tasks", []) if isinstance(t, dict) and t.get("id") == task_id), None)
        if task is None:
            return
        kind: str = str(task.get("kind", "search"))
        instruction: str = str(task.get("instruction", ""))
        state_copy: Dict[str, Any] = json.loads(json.dumps(record.get("state", {}), ensure_ascii=False))
    goal: str = str(state_copy.get("goal", ""))
    try:
        if kind == "search":
            conclusion, detail, sources = _run_search(goal, state_copy, instruction)
            _finish_task(session_id, task_id, "done", conclusion, detail, sources, f"查到了：{conclusion}")
        else:
            draft: str = _run_draft(goal, state_copy, instruction)
            _finish_task(session_id, task_id, "done", "已写好", draft, [], "写好了，放在成果页里。")
    except Exception as exc:
        logger.exception("background task failed")
        message: str = BUDGET_MESSAGE if is_budget_error(exc) else "刚才那件事没弄成，我记在成果页了。"
        _finish_task(session_id, task_id, "failed", message if is_budget_error(exc) else "没弄成", "", [], message)


def start_task(session_id: str, kind: str, instruction: str) -> Dict[str, Any]:
    """Create a task and submit it without blocking."""
    task: Dict[str, Any] = {"id": uuid.uuid4().hex, "kind": kind, "instruction": instruction, "status": "running", "conclusion": "", "detail": "", "sources": [], "created_at": store.now_iso()}
    with store.get_lock(session_id):
        record: Optional[Dict[str, Any]] = store.get_session(session_id)
        if record is None:
            raise KeyError(session_id)
